"use strict";(globalThis.webpackChunkmy_website||=[]).push([[62886],{24507(e){e.exports=JSON.parse('{"slug":"conway-era","title":"Conway Era","short":"The Cardano ledger era that brought on-chain governance under CIP-1694 to mainnet.","category":"governance","aliases":["Conway Ledger Era"],"mentalModel":null,"related":["chang","plomin","van-rossem","dijkstra","cip-1694","voltaire","governance-action","drep"],"sources":[],"link":"/hardforks","level":"intermediate","body":"The ledger era of Cardano focused on on-chain governance. Conway introduces DReps, the Constitutional Committee, and the formal governance actions defined by CIP-1694, turning the Voltaire roadmap phase into something users can interact with directly.\\n\\nThe era was rolled out through a series of hard forks rather than a single switch. [Chang](/glossary/chang) opened it on September 1, 2024 (protocol version 9), [Plomin](/glossary/plomin) followed on January 29, 2025 (version 10) and switched on the remaining governance actions, and [van Rossem](/glossary/van-rossem) on July 18, 2026 (version 11) added new Plutus builtins and was the first hard fork ratified entirely through that governance process. The next hard fork, [Dijkstra](/glossary/dijkstra), opens a new ledger era and is targeted for late 2026."}')}}]);